shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ebe5d8;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c8c0af;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.13);
    --navy-bg: #0f1d2b;
    --navy-card: #172a3d;
    --navy-line: #29435c;
    --crimson: #8f2d24;
    --sage: #2e5a44;

    --font-serif-cn: 'Noto Serif SC', 'Songti SC', serif;
    --font-sans-cn: 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-display-en: 'Playfair Display', Georgia, serif;
    --font-serif-en: 'Lora', Georgia, serif;
    --font-sans-en: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
  }

  .wsj-shadow-body {
    font-family: var(--font-serif-cn);
    background-color: var(--paper);
    line-height: 1.85;
    overflow-x: hidden;
  }

  :host([lang="en"]) .wsj-shadow-body {
    font-family: var(--font-serif-en);
    line-height: 1.78;
  }

  /* Strict Bilingual Visibility Rules */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Inline Highlighting */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 2px;
    border-radius: 1px;
    font-weight: 600;
  }

  /* Sticky Top Masthead */
  .wsj-masthead {
    position: sticky;
    top: 0;
    z-index: 100;
    background: rgba(250, 248, 244, 0.96);
    backdrop-filter: blur(8px);
    border-bottom: 1px solid var(--line-strong);
  }

  .masthead-inner {
    max-width: 1200px;
    margin: 0 auto;
    padding: 10px 24px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    gap: 16px;
  }

  .brand-cluster {
    display: flex;
    align-items: baseline;
    gap: 12px;
    flex-wrap: wrap;
  }

  .wsj-wordmark {
    font-family: var(--font-display-en);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.08em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .wsj-section-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    letter-spacing: 0.06em;
    text-transform: uppercase;
    color: var(--accent);
    border-left: 1px solid var(--line-strong);
    padding-left: 12px;
  }

  .lang-switcher {
    display: inline-flex;
    border: 1px solid var(--line-strong);
    background: var(--paper-card);
    border-radius: 3px;
    overflow: hidden;
  }

  .lang-btn {
    border: none;
    background: transparent;
    padding: 5px 12px;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 600;
    color: var(--muted);
    cursor: pointer;
    transition: all 0.18s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  .reading-progress {
    height: 2px;
    background: var(--accent);
    width: 0%;
    transition: width 0.12s linear;
  }

  /* Hero Header */
  .hero-header {
    max-width: 1200px;
    margin: 0 auto;
    padding: 52px 24px 36px;
    border-bottom: 3px double var(--line-strong);
  }

  .hero-kicker {
    display: flex;
    align-items: center;
    gap: 12px;
    font-family: var(--font-mono);
    font-size: 0.76rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--accent);
    margin-bottom: 18px;
  }

  .hero-kicker::before {
    content: "";
    display: inline-block;
    width: 28px;
    height: 2px;
    background: var(--accent);
  }

  .hero-title {
    font-family: var(--font-serif-cn);
    font-weight: 700;
    font-size: clamp(2.1rem, 4.4vw, 3.45rem);
    line-height: 1.22;
    color: var(--ink);
    letter-spacing: -0.01em;
    max-width: 960px;
    margin-bottom: 18px;
  }

  :host([lang="en"]) .hero-title {
    font-family: var(--font-display-en);
    font-weight: 800;
    line-height: 1.12;
  }

  .hero-dek {
    font-family: var(--font-serif-cn);
    font-size: clamp(1.08rem, 1.8vw, 1.32rem);
    line-height: 1.65;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 28px;
  }

  :host([lang="en"]) .hero-dek {
    font-family: var(--font-serif-en);
    font-style: italic;
  }

  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: center;
    gap: 16px;
    padding-top: 18px;
    border-top: 1px solid var(--line);
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
  }

  .byline-name {
    color: var(--ink);
    font-weight: 700;
    letter-spacing: 0.04em;
  }

  /* Top Stakes Ledger Strip */
  .stakes-ribbon {
    max-width: 1200px;
    margin: 0 auto;
    padding: 24px;
    background: var(--paper-card);
    border-bottom: 1px solid var(--line-strong);
  }

  .stakes-grid {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 20px;
  }

  .stake-cell {
    border-left: 2px solid var(--accent);
    padding-left: 14px;
  }

  .stake-num {
    font-family: var(--font-mono);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.2;
    margin-bottom: 4px;
  }

  .stake-label {
    font-family: var(--font-sans-cn);
    font-size: 0.82rem;
    font-weight: 600;
    color: var(--body);
    margin-bottom: 2px;
  }

  :host([lang="en"]) .stake-label {
    font-family: var(--font-sans-en);
  }

  .stake-sub {
    font-family: var(--font-sans-cn);
    font-size: 0.74rem;
    color: var(--muted);
    line-height: 1.4;
  }

  :host([lang="en"]) .stake-sub {
    font-family: var(--font-sans-en);
  }

  /* Main Editorial Container & Asymmetric Grid */
  .editorial-container {
    max-width: 1200px;
    margin: 0 auto;
    padding: 40px 24px 72px;
  }

  .act-divider {
    display: flex;
    align-items: center;
    gap: 16px;
    margin: 56px 0 28px;
    padding-top: 24px;
    border-top: 2px solid var(--ink);
  }

  .act-num {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    background: var(--ink);
    color: var(--paper);
    padding: 3px 9px;
  }

  .act-title {
    font-family: var(--font-sans-cn);
    font-size: 0.95rem;
    font-weight: 700;
    letter-spacing: 0.04em;
    color: var(--ink);
    text-transform: uppercase;
  }

  :host([lang="en"]) .act-title {
    font-family: var(--font-sans-en);
  }

  .asymmetric-stage {
    display: grid;
    grid-template-columns: minmax(0, 1.85fr) minmax(280px, 1fr);
    gap: 48px;
    align-items: start;
  }

  .prose-column {
    min-width: 0;
  }

  .side-rail {
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 28px;
    position: sticky;
    top: 76px;
  }

  /* Prose Styling (Strict Chinese Typography Rules) */
  .prose-p {
    font-size: 1.125rem;
    color: var(--body);
    margin-bottom: 1.55rem;
    text-align: left;
  }

  .prose-p.lead-para {
    font-size: 1.24rem;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 18px;
    margin-bottom: 1.75rem;
  }

  .prose-p.pivot-line {
    font-family: var(--font-serif-cn);
    font-size: 1.28rem;
    font-weight: 700;
    color: var(--crimson);
    background: var(--paper-card);
    border-left: 4px solid var(--crimson);
    padding: 14px 20px;
    margin: 2rem 0;
  }

  :host([lang="en"]) .prose-p.pivot-line {
    font-family: var(--font-display-en);
  }

  /* Derived Metric & Quote Cards */
  .metric-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--accent);
    padding: 20px;
  }

  .metric-card .metric-val {
    font-family: var(--font-mono);
    font-size: 1.85rem;
    font-weight: 700;
    color: var(--accent);
    line-height: 1.15;
    margin-bottom: 6px;
  }

  .metric-card .metric-lbl {
    font-family: var(--font-sans-cn);
    font-size: 0.85rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 8px;
  }

  :host([lang="en"]) .metric-card .metric-lbl {
    font-family: var(--font-sans-en);
  }

  .metric-card .metric-note {
    font-size: 0.82rem;
    line-height: 1.55;
    color: var(--muted);
  }

  .pull-quote {
    background: var(--paper-card);
    border-top: 2px solid var(--ink);
    border-bottom: 1px solid var(--line-strong);
    padding: 22px 20px;
  }

  .pull-quote .quote-text {
    font-family: var(--font-serif-cn);
    font-size: 1.08rem;
    font-weight: 600;
    line-height: 1.65;
    color: var(--ink);
    margin-bottom: 10px;
  }

  :host([lang="en"]) .pull-quote .quote-text {
    font-family: var(--font-display-en);
    font-style: italic;
  }

  .pull-quote .quote-attrib {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.05em;
  }

  /* Bespoke Editorial Dossier Cards */
  .dossier-box {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 22px;
  }

  .dossier-kicker {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 8px;
  }

  .dossier-title {
    font-family: var(--font-sans-cn);
    font-size: 1rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 14px;
    padding-bottom: 8px;
    border-bottom: 1px solid var(--line);
  }

  :host([lang="en"]) .dossier-title {
    font-family: var(--font-sans-en);
  }

  .cast-list {
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .cast-item {
    padding-bottom: 12px;
    border-bottom: 1px dashed var(--line-strong);
  }

  .cast-item:last-child {
    padding-bottom: 0;
    border-bottom: none;
  }

  .cast-head {
    display: flex;
    justify-content: space-between;
    align-items: baseline;
    gap: 8px;
    margin-bottom: 4px;
  }

  .cast-name {
    font-family: var(--font-sans-cn);
    font-weight: 700;
    font-size: 0.9rem;
    color: var(--ink);
  }

  :host([lang="en"]) .cast-name {
    font-family: var(--font-sans-en);
  }

  .cast-role {
    font-family: var(--font-mono);
    font-size: 0.68rem;
    padding: 2px 6px;
    background: var(--paper-deep);
    color: var(--body);
    border-radius: 2px;
  }

  .cast-desc {
    font-size: 0.82rem;
    line-height: 1.5;
    color: var(--muted);
  }

  /* Full-Bleed Analytical Graphic Panel */
  .graphic-panel {
    margin: 38px 0;
    background: var(--navy-bg);
    color: #f4f1ea;
    border: 1px solid var(--navy-line);
    padding: 28px 26px;
    border-radius: 2px;
  }

  .graphic-header {
    display: flex;
    justify-content: space-between;
    align-items: flex-start;
    flex-wrap: wrap;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 14px;
    border-bottom: 1px solid var(--navy-line);
  }

  .graphic-eyebrow {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: #e28743;
    margin-bottom: 4px;
  }

  .graphic-heading {
    font-family: var(--font-sans-cn);
    font-size: 1.18rem;
    font-weight: 700;
    color: #ffffff;
  }

  :host([lang="en"]) .graphic-heading {
    font-family: var(--font-sans-en);
  }

  .graphic-sub {
    font-size: 0.84rem;
    color: #b0c0d0;
    margin-top: 4px;
  }

  .svg-wrap {
    width: 100%;
    overflow: hidden;
  }

  .svg-wrap svg {
    display: block;
    width: 100%;
    height: auto;
  }

  .graphic-caption {
    margin-top: 14px;
    padding-top: 12px;
    border-top: 1px solid var(--navy-line);
    font-family: var(--font-mono);
    font-size: 0.72rem;
    color: #8fa5ba;
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 8px;
  }

  /* Paper-Themed Annexation Diagram Box */
  .paper-graphic-panel {
    margin: 34px 0;
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-left: 4px solid var(--ink);
    padding: 24px;
  }

  .paper-graphic-panel .graphic-eyebrow {
    color: var(--accent);
  }

  .paper-graphic-panel .graphic-heading {
    color: var(--ink);
  }

  .paper-graphic-panel .graphic-sub {
    color: var(--muted);
  }

  /* Climactic Verdict Quote Box (p23) */
  .verdict-coda {
    margin-top: 32px;
    background: var(--ink);
    color: var(--paper);
    padding: 32px 28px;
    border-left: 5px solid var(--accent);
  }

  .verdict-coda-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: #e28743;
    margin-bottom: 12px;
  }

  .verdict-coda .prose-p {
    color: var(--paper);
    font-size: 1.22rem;
    line-height: 1.75;
    margin-bottom: 0;
  }

  /* Footer */
  .wsj-footer {
    max-width: 1200px;
    margin: 0 auto;
    padding: 28px 24px 64px;
    border-top: 1px solid var(--line-strong);
    display: flex;
    justify-content: space-between;
    flex-wrap: wrap;
    gap: 16px;
    font-family: var(--font-mono);
    font-size: 0.75rem;
    color: var(--muted);
  }

  /* Responsive Mobile Reflow */
  @media (max-width: 920px) {
    .stakes-grid {
      grid-template-columns: repeat(2, 1fr);
    }
    .asymmetric-stage {
      grid-template-columns: 1fr;
      gap: 32px;
    }
    .side-rail {
      position: static;
    }
  }

  @media (max-width: 560px) {
    .masthead-inner {
      padding: 10px 16px;
    }
    .hero-header {
      padding: 32px 16px 24px;
    }
    .stakes-ribbon {
      padding: 18px 16px;
    }
    .stakes-grid {
      grid-template-columns: 1fr;
      gap: 16px;
    }
    .editorial-container {
      padding: 24px 16px 48px;
    }
    .graphic-panel,
    .paper-graphic-panel,
    .verdict-coda {
      padding: 18px 16px;
    }
    .prose-p {
      font-size: 1.05rem;
    }
    .prose-p.lead-para {
      font-size: 1.12rem;
    }
  }
